index 761f866..bdb3fcb 100644
--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -1993,6 +1993,125 @@ extern "C" void c_cedebug(natl id, const char *buf, natq quanti)
 //   ESAME 2024-01-10 )

 // ( SOLUZIONE 2024-01-10
+
+/**
+ * @brief Driver per le periferiche CE.
+ *
+ * Chiamato quando arriva un'interruzione da una periferica CE.
+ * Legge un byte dal registro RBR e lo memorizza nel buffer.
+ * Se tutti i byte sono stati letti, disabilita le interruzioni
+ * e segnala il semaforo di sincronizzazione.
+ *
+ * @param id indice della periferica CE
+ */
+extern "C" void c_driver_ce(natl id)
+{
+	des_ce *ce = &array_ce[id];
+	
+	// se non c'è un'operazione in corso, ignoriamo l'interruzione
+	if (!ce->enabled)
+		return;
+	
+	// leggiamo un byte dal registro RBR
+	char c = inputb(ce->iRBR);
+	
+	// scriviamo il byte nel buffer
+	*ce->buf = c;
+	ce->buf++;
+	ce->quanti--;
+	
+	// se abbiamo letto tutti i byte richiesti
+	if (ce->quanti == 0) {
+		// disabilitiamo le interruzioni della periferica
+		outputb(0, ce->iCTL);
+		// segnaliamo che l'operazione è terminata
+		ce->enabled = false;
+		sem_signal(ce->sync);
+	}
+}
+
+/**
+ * @brief Parte C++ della primitiva ceread_n_to().
+ *
+ * Legge n byte da una periferica CE con timeout.
+ *
+ * @param id 		indice della periferica
+ * @param buf 		buffer per i dati letti
+ * @param quanti 	in: numero di byte da leggere; out: numero di byte letti
+ * @param to 		timeout
+ * @return 		true se l'operazione è completa, false se scaduto il timeout
+ */
+extern "C" bool c_ceread_n_to(natl id, char *buf, natq& quanti, natl to)
+{
+	// validazione id
+	if (id >= next_ce) {
+		flog(LOG_WARN, "ceread_n_to: id non valido: %u", id);
+		c_abort_p();
+		return false;
+	}
+	
+	// controllo Cavallo di Troia sul buffer
+	if (!c_access((vaddr)buf, quanti, true, true)) {
+		flog(LOG_WARN, "ceread_n_to: Cavallo di Troia");
+		c_abort_p();
+		return false;
+	}
+	
+	// timeout pari a zero
+	if (to == 0) {
+		flog(LOG_WARN, "ceread_n_to: timeout pari a zero");
+		c_abort_p();
+		return false;
+	}
+	
+	des_ce *ce = &array_ce[id];
+	natl remaining;
+	
+	// acquisiamo il semaforo di mutua esclusione con timeout
+	remaining = sem_wait_to(ce->mutex, to);
+	if (remaining == 0) {
+		// timeout scattato prima di ottenere il mutex
+		// quanti rimane il valore originale (nessun byte letto)
+		esecuzione->contesto[I_RAX] = 0;  // false
+		return false;
+	}
+	
+	// prepariamo il trasferimento
+	ce->enabled = true;
+	ce->buf = buf;
+	ce->quanti = (natl)quanti;
+	
+	// abilitiamo la periferica (scrivo 1 in CTL)
+	outputb(1, ce->iCTL);
+	
+	// attendiamo il completamento con timeout residuo
+	natl wait_result = sem_wait_to(ce->sync, remaining);
+	
+	if (wait_result == 0) {
+		// timeout scattato: l'operazione non è completa
+		// disabilitiamo le interruzioni della periferica
+		outputb(0, ce->iCTL);
+		ce->enabled = false;
+		
+		// aggiorniamo quanti con il numero di byte effettivamente letti
+		quanti = (natl)quanti - ce->quanti;
+		
+		// rilasciamo il mutex
+		sem_signal(ce->mutex);
+		
+		esecuzione->contesto[I_RAX] = 0;  // false
+		return false;
+	}
+	
+	// operazione completata con successo
+	// quanti è già stato aggiornato (tutti i byte letti)
+	
+	// rilasciamo il mutex
+	sem_signal(ce->mutex);
+	
+	esecuzione->contesto[I_RAX] = 1;  // true
+	return true;
+}
 //   SOLUZIONE 2024-01-10 )

